def view(ax,title,limit=535):
 ax.view_init(elev=12,azim=-58);ax.set(xlabel='x (µm)',ylabel='y (µm)',zlabel='z (µm)',title=title,xlim=[-340,340],ylim=[-340,340],zlim=[-limit,limit],xticks=[-200,0,200],yticks=[-200,200],zticks=[-500,0,500]);ax.set_box_aspect([.68,.68,1.07]);ax.tick_params(labelsize=11,pad=1)
 for axis in [ax.xaxis,ax.yaxis,ax.zaxis]:axis.pane.set_facecolor((.96,.96,.96,1));axis._axinfo['grid'].update(color=(.40,.40,.40,.65),linewidth=.8)
def savefig(fig,name):
 for ext in ['png','svg']:fig.savefig(FIG/(name+'.'+ext),dpi=220,bbox_inches='tight',facecolor='white')
 plt.close(fig)
def main():
 FIG.mkdir(parents=True,exist_ok=True);E=json.loads((BASE/'ENERGY_AND_EQUILIBRIUM_AUDIT.json').read_text());S=json.loads((BASE/'A0_FIRST_FAILURE_SEARCH.json').read_text());F=json.loads((BASE/'CONTINUUM_REFERENCE_AUDIT.json').read_text());candidate=E['lps'][-1];z=np.load(BASE/'lps'/candidate['name']/'equilibrium.npz');refs=[np.load(OLD/f'A{j}/reference.npz') for j in range(3)]
