 f=np.load(BASE/'continuum/refined/A0/equilibrium.npz');X=f['vertices_m']*1e6;xf=X+30*f['vertex_displacement_m']*1e6;cr=f['facets'][f['crack_facets']];ax=fig.add_subplot(2,3,4,projection='3d');ax.add_collection3d(Poly3DCollection(xf[cr],facecolors=TEAL,edgecolors='#15665f',linewidths=.35,alpha=.65));ctrl=np.unique(f['low_dofs']//3);ax.scatter(*X[np.isclose(abs(X[:,2]),475)].T,c=BLUE,s=6,alpha=.5,depthshade=False)
