 ax=fig.add_subplot(2,3,5);fac=f['facets'];side=fac[np.all(np.isclose(X[fac,1],-300),axis=1)];lines=np.concatenate([X[side[:,[0,1]]][:,:,[0,2]],X[side[:,[1,2]]][:,:,[0,2]],X[side[:,[2,0]]][:,:,[0,2]]]);ax.add_collection(LineCollection(lines,colors=GRAY,lw=.45,alpha=.7));ax.plot([-300,-100],[0,0],c=TEAL,lw=3);ax.plot([-100,-100],[-85,85],c=GOLD,lw=1.6,ls='--');ax.set(xlim=[-310,310],ylim=[-180,180],xlabel='Reference x (µm)',ylabel='Reference z (µm)',title='Refined mesh: actual y = −300 µm face');ax.set_aspect('equal')
 ax=fig.add_subplot(2,3,6);ax.plot([-300,300,300,-300,-300],[-500,-500,500,500,-500],c=GRAY,lw=2)
 for h in [-475,475]:ax.plot([-300,300],[h,h],c=BLUE,lw=2)
 ax.scatter(np.tile([-275,275],2),np.repeat([-475,475],2),c=RED,s=25,zorder=4);ax.annotate('',(335,475),(335,-475),arrowprops=dict(arrowstyle='<->',color=BLUE,lw=1.8));ax.text(355,0,'950 µm\ncontrol span',va='center',color=BLUE,fontsize=13);ax.annotate('',(-340,500),(-340,-500),arrowprops=dict(arrowstyle='<->',color=GRAY,lw=1.8));ax.text(-355,0,'1000 µm nominal height',rotation=90,va='center',ha='right',fontsize=13);ax.set(xlim=[-450,640],ylim=[-540,540],xlabel='x (µm)',ylabel='z (µm)',title='Control planes ≠ physical outer faces',xticks=[-300,0,300],yticks=[-500,0,500]);ax.text(0,0,'25 µm outer caps\non both ends',ha='center',fontsize=12)
 fig.suptitle('1 | Compatible geometry with an explicit boundary-mapping limitation\nB = 600 µm; Δa = 50 µm; ΔA = 3.0 × 10⁻⁸ m²; identical total opening = 2 µm',fontsize=20)
