 axs[0,0].set(xlabel='Crack length a (µm)',ylabel='Stored energy U (pJ)',title='Actual low-load equilibrium energies',xticks=aa);axs[0,0].legend();axs[0,1].set(xticks=[0,1],xticklabels=['Two point','Three point'],ylabel='G drive (µJ/m²)',title=f'LPS / refined FEM − 1: {100*rows[-1]["LPS_minus_reference_over_reference_three"]:.3f}% (three point)');axs[0,1].legend()
