 maxres=max(r['relative_free_force'] for r in E['continuum']);maxwork=max(r['work_energy_relative'] for r in E['continuum']);fig.suptitle('2 | Low-load finite-mesh continuum reference vs LPS',fontsize=21);fig.text(.5,.035,f'FEM maximum relative free-force residual = {maxres:.2e}; maximum |2U − u·R| / (2U) = {maxwork:.2e}.\nG refinement stability does not certify volumetric-field convergence. Model / boundary / horizon effects remain unseparated.\nLPS solver energy uncertainty is approximately 10⁻¹⁷ J; errors shown here are distinct from material uncertainty.',ha='center',fontsize=12);savefig(fig,'Fig2_low_load_continuum_comparison')
