 ax=fig.add_subplot(2,2,4,projection='3d',computed_zorder=False);xx=z['x_m']*1e6;ax.scatter(*xx.T,c=RED,s=5,alpha=.23,depthshade=False);ids=np.array(candidate['risk']['symmetric_tie_reference_ids'])-1;b=z['bonds'][ids];ax.add_collection3d(Line3DCollection(xx[b],colors=GOLD,lw=3.5,zorder=10));ax.scatter(*xx[b].reshape(-1,3).T,c=GOLD,s=34,depthshade=False,zorder=11);view(ax,'Unaccepted candidate, deformation ×1\nFour actual grip-corner bond pairs',560)
 fig.suptitle('3 | A0 near-threshold search stopped at the first static acceptance failure',fontsize=20);fig.text(.5,.025,'Filled symbols: accepted baseline. Hollow symbols: actual computed candidate that failed the absolute force gate.\nMaximum bond IDs: '+', '.join(map(str,candidate['risk']['symmetric_tie_reference_ids']))+' (full intact reference, 1-based). No first-failure event was established.',ha='center',fontsize=12);savefig(fig,'Fig3_A0_actual_search_and_location')
 # Failed admission instead of fabricated high-load G.
 fig,axs=plt.subplots(2,2,figsize=(16,11));fig.subplots_adjust(top=.88,bottom=.12,hspace=.35,wspace=.30);h=np.genfromtxt(BASE/'lps'/candidate['name']/'history.csv',names=True,delimiter=',');axs[0,0].semilogy(h['iteration'],h['max_force_N'],c=RED,label='Actual maximum free force');axs[0,0].axhline(1e-13,c='black',ls='--',label='Frozen absolute gate');axs[0,0].set(xlabel='Accepted optimizer iteration',ylabel='Maximum free force (N)',title='Absolute residual gate missed by 11.29×');axs[0,0].legend(fontsize=11)
