 vals=[candidate['risk']['regional_utilization'][n] for n in NAMES];axs[1,0].barh(SHORT,vals,color=COL);axs[1,0].axvline(1,c='black',ls='--');axs[1,0].set(xlabel='s / 0.15 in unaccepted candidate',title='Spatial diagnostic only, no threshold event',xlim=[0,1.08])
 ax=axs[1,1];ax.axis('off');text='HIGH-LOAD PVCE: NOT RUN\n\nA0 candidate: 73.5606 µm, not accepted\nA1 / A2 high-load states: not run\nG high two / three: unavailable\nCritical opening interval: unavailable\n\nNative / independent force difference: 9.35×10⁻¹⁶\nContact energy and force: zero\nNo natural bond deletion; no altered s00\n\nEnergy plateau is not proof of force convergence.\nNumerical stop ≠ physical instability.';ax.text(.0,1,text,transform=ax.transAxes,va='top',fontsize=13,linespacing=1.45)
